template:
@php
    $name = $logo ?: (function_exists('settings') ? settings('general.project-name') : null) ?: config('app.name');
    $items = function_exists('menu') ? menu('header') : [];
@endphp
<header class="b-demo-header" data-wx-block="demo-header">
    <div class="b-demo-header__inner">
        <a class="b-demo-header__name" href="{{ url('/') }}">{{ $name }}</a>
        @if (count($items) > 0)
            <nav class="b-demo-header__menu">
                @foreach ($items as $item)
                    @if ($item->url !== null)
                        <a class="b-demo-header__link @if ($item->isActive()) is-active @endif" @foreach ($item->attrs() as $attribute => $value) {{ $attribute }}="{{ $value }}" @endforeach>{{ $item->label }}</a>
                    @endif
                @endforeach
            </nav>
        @endif
        @if ($button_label)
            <a class="b-demo-header__button" href="{{ $button_url ?: url('/') }}">{{ $button_label }}</a>
        @endif
    </div>
</header>

